-- Seed data for the `goals` table.
-- Generated from the Goals knowledge base export.
-- Notes on transformations applied:
--   * Rows with a non-integer `target` (e.g. ranges/text) were excluded (13 rows).
--   * `type` values were normalized to GoalType constants (UPPER, spaces/hyphens -> underscores).
--   * `category` is set to DAILY_CHALLENGES for every row.
--   * Empty `reward` defaulted to 1; empty `on_completed_entity` -> '' and `on_completed_entity_id` -> 0.
--   * IDs: duplicates kept first occurrence; duplicate-extras and empty IDs were assigned
--     fresh sequential IDs starting at 7303 (5 reassigned, 316 filled).
-- Ignored source columns: conversation to start(/id), scalable?, skills_to_gain(/id), slider?, usage.

ALTER TABLE goals MODIFY COLUMN type     VARCHAR(64) NOT NULL;
ALTER TABLE goals MODIFY COLUMN category VARCHAR(64) NOT NULL;

